11	export const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
12	export const SERVER = join(ROOT, 'server.mjs');
13	export const LISTEN_RE = /^listening on http:\/\/127\.0\.0\.1:(\d+)\n$/;
14	export const JSON_TYPE = 'application/json; charset=utf-8';
15	export const JSON_HEADERS = Object.freeze({ 'Content-Type': 'application/json' });
16	const EXIT_TIMEOUT_MS = 5000;
17	const LISTEN_TIMEOUT_MS = 10000;
18	const REQUEST_TIMEOUT_MS = 15000;
