64	/** Runs fn(dir) with a fresh tmp dir that is always removed. */
65	export async function withTmpDir(fn) {
66	  const dir = await makeTmpDir();
67	  try {
68	    return await fn(dir);
69	  } finally {
70	    await rm(dir, { recursive: true, force: true });
