100	/** Environment without the caller's PORT / DATA_FILE; `undefined` values mean unset. */
101	function buildEnv(env) {
102	  const base = { ...process.env };
103	  delete base.PORT;
104	  delete base.DATA_FILE;
105	  const merged = { ...base, ...env };
106	  return Object.fromEntries(Object.entries(merged).filter(([, v]) => v !== undefined));
107	}
