126	/** Runs the server until it exits by itself; fails if it is still running after the timeout. */
127	export async function runToExit(opts, timeoutMs = EXIT_TIMEOUT_MS) {
128	  const handle = spawnServer(opts);
129	  let timer;
130	  const timeout = new Promise((resolve) => {
131	    timer = setTimeout(() => resolve('timeout'), timeoutMs);
132	  });
133	  const result = await Promise.race([handle.exited, timeout]);
134	  clearTimeout(timer);
135	  if (result === 'timeout') {
136	    handle.child.kill('SIGKILL');
137	    await handle.exited;
138	    throw new Error(`server did not exit; stdout=${JSON.stringify(handle.stdout())}`);
139	  }
140	  return { code: result.code, signal: result.signal, stdout: handle.stdout(), stderr: handle.stderr() };
141	}
